   173→// worktreeGroup groups sessions by worktree path for display.
   174→type worktreeGroup struct {
   175→	path     string
   176→	branch   string
   177→	sessions []*session.State
   178→}
   179→
   180→const unknownPlaceholder = "(unknown)"
   181→
   182→// writeActiveSessions writes active session information grouped by worktree.
   183→func writeActiveSessions(w io.Writer) {
   184→	store, err := session.NewStateStore()
   185→	if err != nil {
   186→		return
   187→	}
   188→
   189→	states, err := store.List(context.Background())
   190→	if err != nil || len(states) == 0 {
   191→		return
   192→	}
   193→
   194→	// Filter to active sessions only
   195→	var active []*session.State
   196→	for _, s := range states {
   197→		if s.EndedAt == nil {
   198→			active = append(active, s)
   199→		}
   200→	}
   201→	if len(active) == 0 {
   202→		return
   203→	}
   204→
   205→	// Group by worktree path
   206→	groups := make(map[string]*worktreeGroup)
   207→	for _, s := range active {
   208→		wp := s.WorktreePath
   209→		if wp == "" {
   210→			wp = unknownPlaceholder
   211→		}
   212→		g, ok := groups[wp]
   213→		if !ok {
   214→			g = &worktreeGroup{path: wp}
   215→			groups[wp] = g
   216→		}
   217→		g.sessions = append(g.sessions, s)
   218→	}
   219→
   220→	// Resolve branch names for each worktree (skip for unknown paths)
   221→	for _, g := range groups {
   222→		if g.path != unknownPlaceholder {
   223→			g.branch = resolveWorktreeBranch(g.path)
   224→		}
   225→	}
   226→
   227→	// Sort groups: alphabetical by path
   228→	sortedGroups := make([]*worktreeGroup, 0, len(groups))
   229→	for _, g := range groups {
   230→		sortedGroups = append(sortedGroups, g)
   231→	}
   232→	sort.Slice(sortedGroups, func(i, j int) bool {
   233→		return sortedGroups[i].path < sortedGroups[j].path
   234→	})
   235→
   236→	// Sort sessions within each group by StartedAt (newest first)
   237→	for _, g := range sortedGroups {
   238→		sort.Slice(g.sessions, func(i, j int) bool {
   239→			return g.sessions[i].StartedAt.After(g.sessions[j].StartedAt)
   240→		})
   241→	}
   242→
   243→	fmt.Fprintln(w)
   244→	fmt.Fprintln(w, "Active Sessions:")
   245→	for i, g := range sortedGroups {
   246→		header := g.path
   247→		if g.branch != "" {
   248→			header += " (" + g.branch + ")"
   249→		}
   250→		fmt.Fprintf(w, "  %s\n", header)
   251→
   252→		for _, st := range g.sessions {
   253→			agentLabel := string(st.AgentType)
   254→			if agentLabel == "" {
   255→				agentLabel = unknownPlaceholder
   256→			}
   257→
   258→			shortID := st.SessionID
   259→			if len(shortID) > 7 {
   260→				shortID = shortID[:7]
   261→			}
   262→
   263→			prompt := st.FirstPrompt
   264→			if prompt == "" {
   265→				prompt = unknownPlaceholder
   266→			}
   267→			prompt = stringutil.TruncateRunes(prompt, 40, "...")
   268→
   269→			age := "started " + timeAgo(st.StartedAt)
   270→
   271→			fmt.Fprintf(w, "    [%s] %-9s \"%s\"  %s\n",
   272→				agentLabel, shortID, prompt, age)
   273→		}
   274→
   275→		// Blank line between groups, but not after the last one
   276→		if i < len(sortedGroups)-1 {
   277→			fmt.Fprintln(w)
   278→		}
   279→	}
   280→}
   281→
   282→// resolveWorktreeBranch resolves the current branch for a worktree path.
   283→func resolveWorktreeBranch(worktreePath string) string {
   284→	cmd := exec.CommandContext(context.Background(), "git", "-C", worktreePath, "rev-parse", "--abbrev-ref", "HEAD")
   285→	output, err := cmd.Output()
   286→	if err != nil {
   287→		return ""
   288→	}
   289→	return strings.TrimSpace(string(output))
   290→}
