   177→func TestTimeAgo(t *testing.T) {
   178→	tests := []struct {
   179→		name     string
   180→		duration time.Duration
   181→		want     string
   182→	}{
   183→		{"just now", 10 * time.Second, "just now"},
   184→		{"30 seconds", 30 * time.Second, "just now"},
   185→		{"1 minute", 1 * time.Minute, "1m ago"},
   186→		{"5 minutes", 5 * time.Minute, "5m ago"},
   187→		{"59 minutes", 59 * time.Minute, "59m ago"},
   188→		{"1 hour", 1 * time.Hour, "1h ago"},
   189→		{"3 hours", 3 * time.Hour, "3h ago"},
   190→		{"23 hours", 23 * time.Hour, "23h ago"},
   191→		{"1 day", 24 * time.Hour, "1d ago"},
   192→		{"7 days", 7 * 24 * time.Hour, "7d ago"},
   193→	}
   194→
   195→	for _, tt := range tests {
   196→		t.Run(tt.name, func(t *testing.T) {
